productCard(product={},options={}){const price=this.money(product.price,product.currency||options.currency||"USD",options.locale);const old=product.compareAt?`<del>${this.money(product.compareAt,product.currency||options.currency||"USD",options.locale)}</del>`:"";return `<article class="ph-product-card" data-product-id="${premiumEscape(product.id||"")}"><a href="${premiumEscape(APP.link(product.href||"#"))}" class="ph-product-media">${product.badge?`<span class="ph-product-badge">${premiumEscape(product.badge)}</span>`:""}<img src="${premiumEscape(product.image||"")}" alt="${premiumEscape(product.alt||product.title||"Product")}" loading="lazy"></a><div class="ph-product-body">${product.category?`<small>${premiumEscape(product.category)}</small>`:""}<h3><a href="${premiumEscape(APP.link(product.href||"#"))}">${premiumEscape(product.title||"Product")}</a></h3>${product.rating!=null?`<div aria-label="${premiumEscape(product.rating)} out of 5">★ ${premiumEscape(product.rating)}</div>`:""}<div class="ph-product-price">${price}${old}</div><button type="button" data-cart-add="${premiumEscape(product.id||"")}" ${product.stock===0?"disabled":""}>${premiumEscape(product.stock===0?"Out of stock":options.button||"Add to cart")}</button></div></article>`},
cart(initial=[]){let items=Array.isArray(initial)?initial.slice():[];const api={items(){return items.slice()},add(item,quantity=1){const id=String(item.id);const found=items.find(row=>String(row.id)===id);if(found)found.quantity=(Number(found.quantity)||0)+quantity;else items.push({...item,quantity});APP.emit("commerce:cart",{type:"add",item,items:api.items()});return api},remove(id){items=items.filter(item=>String(item.id)!==String(id));APP.emit("commerce:cart",{type:"remove",id,items:api.items()});return api},update(id,quantity){const item=items.find(row=>String(row.id)===String(id));if(item)item.quantity=Math.max(0,Number(quantity)||0);items=items.filter(row=>row.quantity>0);APP.emit("commerce:cart",{type:"update",id,items:api.items()});return api},count(){return items.reduce((sum,item)=>sum+(Number(item.quantity)||0),0)},total(){return items.reduce((sum,item)=>sum+(Number(item.price)||0)*(Number(item.quantity)||0),0)},clear(){items=[];APP.emit("commerce:cart",{type:"clear",items:[]});return api}};return api},
